def normalize_team_name(name):
    value = unicodedata.normalize('NFKD', str(name or ''))
    value = ''.join(char for char in value if not unicodedata.combining(char))
    value = value.lower()
    value = value.replace('&', ' and ')
    value = re.sub(r'\b(fc|cf|sc|afc|ac|as|ssc|ss|uc|us|sd|rc|rsc|sv|vfl|vfb|tsg|fsv)\b', ' ', value)
    value = re.sub(r'\b(football club|calcio|club de futbol|de futbol|balompie)\b', ' ', value)
    value = re.sub(r'[^a-z0-9]+', ' ', value)
    value = re.sub(r'\b(19|1901|1909|1913|1924|1927|1899|04|05|29|63|98)\b', ' ', value)
    return re.sub(r'\s+', ' ', value).strip()


