def match_local_team(provider_name):
    normalized = normalize_team_name(provider_name)
    if normalized in TEAM_LOOKUP:
        return TEAM_LOOKUP[normalized]
    if normalized in TEAM_ALIASES:
        return TEAM_ALIASES[normalized]

    provider_words = set(normalized.split())
    best_match = None
    best_score = 0
    for local_team in LOCAL_TEAMS:
        local_words = set(normalize_team_name(local_team).split())
        if not provider_words or not local_words:
            continue
        overlap = len(provider_words & local_words)
        score = overlap / max(len(provider_words), len(local_words))
        if score > best_score:
            best_score = score
            best_match = local_team

    return best_match if best_score >= 0.72 else None


def format_api_datetime(value):
    if not value:
        return None
    try:
        date = datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone()
        return date.strftime('%d %b %Y %H:%M')
    except ValueError:
        return value


def format_match_score(score):
    full_time = (score or {}).get('fullTime') or {}
    half_time = (score or {}).get('halfTime') or {}
    home_score = full_time.get('home')
    away_score = full_time.get('away')
    if home_score is None or away_score is None:
        home_score = half_time.get('home')
        away_score = half_time.get('away')
    if home_score is None or away_score is None:
        return '-'
    return f'{home_score}-{away_score}'


def parse_live_match(match):
    home_provider = (match.get('homeTeam') or {}).get('name') or 'Unknown home team'
    away_provider = (match.get('awayTeam') or {}).get('name') or 'Unknown away team'
    home_local = match_local_team(home_provider)
    away_local = match_local_team(away_provider)

    return {
        'id': match.get('id'),
        'competition': (match.get('competition') or {}).get('name'),
        'status': match.get('status'),
        'minute': match.get('minute'),
        'utc_date': match.get('utcDate'),
        'local_date': format_api_datetime(match.get('utcDate')),
        'last_updated': format_api_datetime(match.get('lastUpdated')),
        'score': format_match_score(match.get('score')),
        'home_provider': home_provider,
        'away_provider': away_provider,
        'home_team': home_local,
        'away_team': away_local,
        'can_predict': bool(home_local and away_local),
    }


def fetch_football_data_matches():
    headers = {'X-Auth-Token': LIVE_API_TOKEN}
    try:
        response = requests.get(
            f'{LIVE_API_BASE_URL}/matches',
            params={'status': 'LIVE'},
            headers=headers,
            timeout=10,
        )
        response.raise_for_status()
    except requests.HTTPError as error:
        if error.response is None or error.response.status_code != 400:
            raise
        response = requests.get(f'{LIVE_API_BASE_URL}/matches', headers=headers, timeout=10)
        response.raise_for_status()

    payload = response.json()
    matches = [parse_live_match(match) for match in payload.get('matches', [])]
    live_matches = [match for match in matches if match.get('status') in LIVE_MATCH_STATUSES]
    return live_matches if live_matches else matches


def get_live_matches(force_refresh=False):
    if not LIVE_API_TOKEN:
        return {
            'configured': False,
            'provider': 'football-data.org',
            'matches': [],
            'fetched_at': None,
            'cache_seconds': LIVE_MATCH_CACHE_SECONDS,
            'message': 'Set FOOTBALL_DATA_API_TOKEN to enable live match sync.',
        }

    now = time.time()
    cached_payload = LIVE_MATCH_CACHE['payload']
    if (
        not force_refresh
        and cached_payload is not None
        and now - LIVE_MATCH_CACHE['fetched_at'] < LIVE_MATCH_CACHE_SECONDS
    ):
        return cached_payload

    matches = fetch_football_data_matches()
    payload = {
        'configured': True,
        'provider': 'football-data.org',
        'matches': matches,
        'fetched_at': datetime.now().isoformat(timespec='seconds'),
        'cache_seconds': LIVE_MATCH_CACHE_SECONDS,
        'message': None,
    }
    LIVE_MATCH_CACHE['fetched_at'] = now
    LIVE_MATCH_CACHE['payload'] = payload
    return payload

# Calculate team strengths and defenses
@lru_cache(maxsize=None)
def get_team_stats():
    window = 10
    stats_df = df.copy()
    stats_df['home_strength'] = stats_df.groupby('home_team')['home_goals'].transform(lambda x: x.rolling(window, min_periods=1).mean())
    stats_df['away_strength'] = stats_df.groupby('away_team')['away_goals'].transform(lambda x: x.rolling(window, min_periods=1).mean())
    stats_df['home_defense'] = stats_df.groupby('home_team')['away_goals'].transform(lambda x: x.rolling(window, min_periods=1).mean())
    stats_df['away_defense'] = stats_df.groupby('away_team')['home_goals'].transform(lambda x: x.rolling(window, min_periods=1).mean())
    home_strength = stats_df.groupby('home_team')['home_strength'].last().to_dict()
    away_strength = stats_df.groupby('away_team')['away_strength'].last().to_dict()
    home_defense = stats_df.groupby('home_team')['home_defense'].last().to_dict()
    away_defense = stats_df.groupby('away_team')['away_defense'].last().to_dict()
    return home_strength, away_strength, home_defense, away_defense

@lru_cache(maxsize=None)
def get_base_team_strength():
    return df.groupby('home_team')['home_goals'].mean().to_dict()

def safe_mean(series, fallback):
    value = series.mean()
    return fallback if pd.isna(value) else value

def poisson_pmf(goal_count, expected_goals):
    expected_goals = max(float(expected_goals), 0.05)
    return np.exp(-expected_goals) * (expected_goals ** goal_count) / math.factorial(goal_count)

def build_poisson_analysis(home_expected_goals, away_expected_goals, max_goals=6):
    home_expected_goals = float(np.clip(home_expected_goals, 0.05, 6))
    away_expected_goals = float(np.clip(away_expected_goals, 0.05, 6))
    home_probs = [poisson_pmf(i, home_expected_goals) for i in range(max_goals + 1)]
    away_probs = [poisson_pmf(i, away_expected_goals) for i in range(max_goals + 1)]

    score_matrix = []
    score_rows = []
    exact_scores = []
    home_win_probability = 0
    draw_probability = 0
    away_win_probability = 0
    over_probabilities = {1.5: 0, 2.5: 0, 3.5: 0}

    for home_goals, home_probability in enumerate(home_probs):
        row = []
        for away_goals, away_probability in enumerate(away_probs):
            probability = home_probability * away_probability
            probability_pct = float(probability * 100)
            row.append(round(probability_pct, 2))
            exact_scores.append({
                'score': f'{home_goals}-{away_goals}',
                'home_goals': home_goals,
                'away_goals': away_goals,
                'probability': probability_pct
            })

            if home_goals > away_goals:
                home_win_probability += probability
            elif home_goals == away_goals:
                draw_probability += probability
            else:
                away_win_probability += probability

            total_goals = home_goals + away_goals
            for line in over_probabilities:
                if total_goals > line:
                    over_probabilities[line] += probability
        score_rows.append(row)

    for home_goals, row in enumerate(score_rows):
        score_matrix.append({
            'home_goals': home_goals,
            'probabilities': row
        })

    top_exact_scores = sorted(exact_scores, key=lambda item: item['probability'], reverse=True)[:8]
    btts_probability = 1 - np.exp(-home_expected_goals) - np.exp(-away_expected_goals) + np.exp(-(home_expected_goals + away_expected_goals))

    return {
        'expected_goals': {
            'home': round(home_expected_goals, 2),
            'away': round(away_expected_goals, 2)
        },
        'score_goals': list(range(max_goals + 1)),
        'score_matrix': score_matrix,
        'top_exact_scores': [
            {
                'score': item['score'],
                'probability': round(item['probability'], 2)
            }
            for item in top_exact_scores
        ],
        'poisson_probabilities': {
            'home_win': round(home_win_probability * 100, 2),
            'draw': round(draw_probability * 100, 2),
            'away_win': round(away_win_probability * 100, 2)
        },
        'markets': {
            'btts_yes': round(float(btts_probability * 100), 2),
            'btts_no': round(float((1 - btts_probability) * 100), 2),
            'over_1_5': round(float(over_probabilities[1.5] * 100), 2),
            'under_1_5': round(float((1 - over_probabilities[1.5]) * 100), 2),
            'over_2_5': round(float(over_probabilities[2.5] * 100), 2),
            'under_2_5': round(float((1 - over_probabilities[2.5]) * 100), 2),
            'over_3_5': round(float(over_probabilities[3.5] * 100), 2),
            'under_3_5': round(float((1 - over_probabilities[3.5]) * 100), 2)
        }
    }

def blend_probabilities(model_probabilities, poisson_probabilities):
    blended = {}
    for outcome in ['home_win', 'draw', 'away_win']:
        blended[outcome] = round((model_probabilities.get(outcome, 0) + poisson_probabilities.get(outcome, 0)) / 2, 2)
    return blended

def selected_result_method():
    if not ml_available:
        return 'historical_poisson'
    if not model_metadata:
        return 'ml_ensemble'
    production = model_metadata.get('metrics', {}).get('production', {})
    if production.get('result_method'):
        return production['result_method']
    metrics = model_metadata.get('metrics', {})
    poisson_accuracy = metrics.get('baselines', {}).get('poisson_accuracy', 0)
    ml_accuracy = metrics.get('result_model', {}).get('accuracy', 0)
    return 'historical_poisson' if poisson_accuracy >= ml_accuracy else 'ml_ensemble'

def prediction_from_probabilities(probabilities):
    return max(probabilities.items(), key=lambda item: item[1])[0]

def fallback_goal_estimate(value, fallback=1.0):
    return fallback if pd.isna(value) else max(float(value), 0)

# Calculate head-to-head statistics
@lru_cache(maxsize=None)
def get_h2h_stats():
    def calculate_h2h(group):
        home_wins = (group['home_goals'] > group['away_goals']).sum()
        away_wins = (group['home_goals'] < group['away_goals']).sum()
        draws = (group['home_goals'] == group['away_goals']).sum()
        total_matches = len(group)
        return {
            'h2h_home_win_rate': home_wins / total_matches if total_matches > 0 else 0.5,
            'h2h_away_win_rate': away_wins / total_matches if total_matches > 0 else 0.5,
            'h2h_draw_rate': draws / total_matches if total_matches > 0 else 0.5
        }
    return df.groupby(['home_team', 'away_team']).apply(calculate_h2h).to_dict()

def get_h2h_history(home_team, away_team, n=5):
    matches = df[(df['home_team'] == home_team) & (df['away_team'] == away_team) |
                 (df['home_team'] == away_team) & (df['away_team'] == home_team)]
    
    matches = matches.sort_values('date', ascending=False).drop_duplicates(subset=['date', 'home_team', 'away_team'])
    matches = matches.head(n)
    
    history = []
    for _, match in matches.iterrows():
        date_obj = match['date']
        formatted_date = date_obj.strftime('%d %b %Y')
        
        if match['home_team'] == home_team:
            result = 'home_win' if match['home_goals'] > match['away_goals'] else 'away_win' if match['home_goals'] < match['away_goals'] else 'draw'
            history.append({
                'date': formatted_date,
                'home_team': match['home_team'],
                'away_team': match['away_team'],
                'score': f"{match['home_goals']}-{match['away_goals']}",
                'result': result
            })
        else:
            result = 'away_win' if match['home_goals'] > match['away_goals'] else 'home_win' if match['home_goals'] < match['away_goals'] else 'draw'
            history.append({
                'date': formatted_date,
                'home_team': match['away_team'],
                'away_team': match['home_team'],
                'score': f"{match['away_goals']}-{match['home_goals']}",
                'result': result
            })
    return history

def get_team_last_matches(team, n=5):
    current_date = datetime.now()
    home_matches = df[(df['home_team'] == team) & (df['date'] < current_date)].sort_values('date', ascending=False).head(n)
    away_matches = df[(df['away_team'] == team) & (df['date'] < current_date)].sort_values('date', ascending=False).head(n)
    
    all_matches = pd.concat([home_matches, away_matches]).sort_values('date', ascending=False).head(n)
    
    history = []
    for _, match in all_matches.iterrows():
        date_obj = match['date']
        formatted_date = date_obj.strftime('%d %b %Y')
        
        if match['home_team'] == team:
            result = 'win' if match['home_goals'] > match['away_goals'] else 'loss' if match['home_goals'] < match['away_goals'] else 'draw'
            history.append({
                'date': formatted_date,
                'opponent': match['away_team'],
                'score': f"{match['home_goals']}-{match['away_goals']}",
                'result': result
            })
        else:
            result = 'win' if match['away_goals'] > match['home_goals'] else 'loss' if match['away_goals'] < match['home_goals'] else 'draw'
            history.append({
                'date': formatted_date,
                'opponent': match['home_team'],
                'score': f"{match['away_goals']}-{match['home_goals']}",
                'result': result
            })
    return history

@app.route('/')
def home():
    return render_template('index.html')

@app.route('/predict', methods=['POST'])
def predict():
    data = request.json
    home_team = data['home_team']
    away_team = data['away_team']

    try:
        prediction_input = build_prediction_frame(honest_feature_context, home_team, away_team, datetime.now())

        # Predict scores
        if score_model_available:
            home_goals_pred = home_goals_model.predict(prediction_input)[0]
            away_goals_pred = away_goals_model.predict(prediction_input)[0]
        else:
            home_goals_pred = fallback_goal_estimate(prediction_input['home_avg_goals_for'].iloc[0])
            away_goals_pred = fallback_goal_estimate(prediction_input['away_avg_goals_for'].iloc[0])

        poisson_home_expected = prediction_input['poisson_home_expected_goals'].iloc[0]
        poisson_away_expected = prediction_input['poisson_away_expected_goals'].iloc[0]
        if pd.isna(poisson_home_expected):
            poisson_home_expected = home_goals_pred
        if pd.isna(poisson_away_expected):
            poisson_away_expected = away_goals_pred

        poisson_analysis = build_poisson_analysis(poisson_home_expected, poisson_away_expected)
        ml_prediction = None
        ml_probability_dict = poisson_analysis['poisson_probabilities']

        if ml_available:
            prediction_encoded = model.predict(prediction_input)
            ml_prediction = le.inverse_transform(prediction_encoded)[0]

            probabilities = model.predict_proba(prediction_input)[0]
            ml_probability_dict = {le.classes_[i]: float(prob) * 100 for i, prob in enumerate(probabilities)}

        blended_probabilities = (
            blend_probabilities(ml_probability_dict, poisson_analysis['poisson_probabilities'])
            if ml_available
            else poisson_analysis['poisson_probabilities']
        )
        result_method = selected_result_method()
        probability_dict = poisson_analysis['poisson_probabilities'] if result_method == 'historical_poisson' else ml_probability_dict
        prediction = prediction_from_probabilities(probability_dict)

        estimated_score = poisson_analysis['top_exact_scores'][0]['score']
        score_model_estimate = f"{home_goals_pred:.2f}-{away_goals_pred:.2f}"

        h2h_history = get_h2h_history(home_team, away_team)
        home_team_last_matches = get_team_last_matches(home_team)
        away_team_last_matches = get_team_last_matches(away_team)
        
        return jsonify({
            'prediction': prediction,
            'prediction_method': result_method,
            'model_prediction': ml_prediction,
            'ml_available': ml_available,
            'probabilities': probability_dict,
            'ml_probabilities': ml_probability_dict,
            'poisson_probabilities': poisson_analysis['poisson_probabilities'],
            'blended_probabilities': blended_probabilities,
            'predicted_score': estimated_score,
            'score_model_estimate': score_model_estimate,
            'poisson_analysis': poisson_analysis,
            'model_evaluation': model_metadata['metrics'] if model_metadata else None,
            'h2h_history': h2h_history,
            'home_team_last_matches': home_team_last_matches,
            'away_team_last_matches': away_team_last_matches
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/teams', methods=['GET'])
def get_teams():
    return jsonify(LOCAL_TEAMS)

@app.route('/live-matches', methods=['GET'])
def get_live_matches_endpoint():
    force_refresh = request.args.get('refresh') == '1'
    try:
        return jsonify(get_live_matches(force_refresh=force_refresh))
    except requests.HTTPError as error:
        status_code = error.response.status_code if error.response is not None else 502
        provider_message = None
        if error.response is not None:
            try:
                provider_message = error.response.json().get('message')
            except ValueError:
                provider_message = error.response.text
        return jsonify({
            'configured': True,
            'provider': 'football-data.org',
            'matches': [],
            'error': provider_message or str(error),
        }), min(status_code, 599)
    except requests.RequestException as error:
        return jsonify({
            'configured': True,
            'provider': 'football-data.org',
            'matches': [],
            'error': str(error),
        }), 502

@app.route('/model-evaluation', methods=['GET'])
def get_model_evaluation():
    if not model_metadata:
        return jsonify({'error': 'model_metadata.joblib not found'}), 404
    return jsonify(model_metadata['metrics'])

if __name__ == '__main__':
    app.run(debug=True)
